// Indexed by game::MobKind. The order here is the enum's order, and the
// static_assert in render.cpp is what keeps it that way.
struct MobArt {
  const uint8_t* pix;      // FRAMES * H * W
  const uint8_t (*pal)[3];
  uint8_t w, h, frames, colours;
  // Frames are view-major: `walk` of them per view, for `views` views,
  // and then whatever attack poses the family has.
  //
  //   [0, walk)              FRONT walk cycle
  //   [walk, 2*walk)         SIDE  walk cycle -- MIRRORED by drawMobs
  //                          for the far side, so it is drawn once
  //   [2*walk, 3*walk)       BACK  walk cycle
  //   [views*walk, frames)   attack poses, FRONT only: a mob swinging
  //                          at you is looking at you by construction
  uint8_t views;
  uint8_t walk;
  float   worldH;          // how tall it stands, in blocks
};

